public class GenericClassDemo {
    // A generic Result container modeling Success or Failure
    static class Result<T> {
        private final T data;
        private final String errorMessage;
        private final boolean success;

        private Result(T data, String errorMessage, boolean success) {
            this.data = data;
            this.errorMessage = errorMessage;
            this.success = success;
        }

        public static <T> Result<T> ok(T data) {
            return new Result<>(data, null, true);
        }

        public static <T> Result<T> fail(String error) {
            return new Result<>(null, error, false);
        }

        public boolean isSuccess() { return success; }
        public T getData() { return data; }
        public String getErrorMessage() { return errorMessage; }
    }

    public static void main(String[] args) {
        // Diamond operator <> automatically infers types
        Result<String> userResult = Result.ok("User_Alice_Authenticated");
        Result<Integer> balanceResult = Result.ok(15000);
        Result<Double> failedResult = Result.fail("Insufficient funds");

        if (userResult.isSuccess()) {
            System.out.println("User Data: " + userResult.getData().toLowerCase());
        }
        if (balanceResult.isSuccess()) {
            System.out.println("Balance:   $" + balanceResult.getData());
        }
        if (!failedResult.isSuccess()) {
            System.out.println("Error:     " + failedResult.getErrorMessage());
        }
    }
}
// Expected Output:
// User Data: user_alice_authenticated
// Balance:   $15000
// Error:     Insufficient funds

