public class PairDemo {
    public static class Pair<A, B> {
        private final A first;
        private final B second;

        public Pair(A first, B second) {
            this.first = first;
            this.second = second;
        }

        public A getFirst() { return first; }
        public B getSecond() { return second; }

        @Override
        public String toString() {
            return "(" + first + ", " + second + ")";
        }
    }

    public static void main(String[] args) {
        Pair<String, Integer> studentGrade = new Pair<>("Alice", 98);
        Pair<Integer, Boolean> flag = new Pair<>(404, false);

        System.out.println("Student: " + studentGrade.getFirst() + ", Score: " + studentGrade.getSecond());
        System.out.println("Status:  " + flag);
    }
}

