public class Maybe<T> {
    private final T value;
    private final boolean present;

    private Maybe(T value, boolean present) {
        this.value = value;
        this.present = present;
    }

    public static <T> Maybe<T> of(T value) {
        if (value == null) throw new NullPointerException("Value cannot be null");
        return new Maybe<>(value, true);
    }

    public static <T> Maybe<T> empty() {
        return new Maybe<>(null, false);
    }

    public boolean isPresent() {
        return present;
    }

    public T get() {
        if (!present) throw new IllegalStateException("No value present");
        return value;
    }

    public T orElse(T fallback) {
        return present ? value : fallback;
    }

    public static void main(String[] args) {
        Maybe<String> present = Maybe.of("Configured");
        Maybe<String> empty = Maybe.empty();
        System.out.println(present.get());
        System.out.println(empty.orElse("DefaultValue"));
    }
}

