public class Holder<T> {
    private T value;

    public Holder(T value) {
        this.value = value;
    }

    public T get() {
        return value;
    }

    public void swap(Holder<T> other) {
        if (other != null) {
            T temp = this.value;
            this.value = other.value;
            other.value = temp;
        }
    }

    public static void main(String[] args) {
        Holder<String> h1 = new Holder<>("First");
        Holder<String> h2 = new Holder<>("Second");
        h1.swap(h2);
        System.out.println(h1.get());
        System.out.println(h2.get());
    }
}
